from pathlib import Path
import re,json,hashlib,subprocess
r=Path.cwd();o=r/'.work/local-call-20261116';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
sourcefiles=[n for n in subprocess.check_output(['git','ls-files','src','build.zig'],text=True).splitlines() if (r/n).is_file()]
hashes={n:sha(r/n) for n in sourcefiles};differences={n:{'root':h,'snapshot':sha(r/'.work/rot3-20261116/baseline'/n)} for n,h in hashes.items() if sha(r/'.work/rot3-20261116/baseline'/n)!=h};assert all(n.startswith('src/tests/') for n in differences)
symbols=(o/'windows-symbols.txt').read_text();win=(o/'windows-disassembly.txt').read_text();linux=(r/'.work/stack-check-20261116/baseline-disassembly.txt').read_text()
report={'source_hashes':hashes,'snapshot_matches':'all tracked src runtime files and build.zig match baseline snapshot; test source difference recorded','test_source_differences':differences,'scope':'symbol-bearing adopted-source binaries; not byte-identical to stripped timing executable; no Windows runtime path counts','windows':{},'linux':{}}
for name in ['fetchLocal','storeLocal']:
 m=re.search(r'S_LPROC32[^\n]* `'+name+r'`\n[^\n]*addr = 0001:(\d+), code size = (\d+)',symbols);assert m,name
 start=0x140001000+int(m[1]);size=int(m[2]);lines=[];calls=[]
 for line in win.splitlines():
  ins=re.match(r'^([0-9a-f]+):',line)
  if ins and start<=int(ins[1],16)<start+size:lines.append(line)
  if re.search(r'\bcall\s+0x'+f'{start:x}'+r'\b',line):calls.append(line)
 assert lines and calls
 report['windows'][name]={'va':hex(start),'bytes':size,'assembly':'\n'.join(lines),'call_sites':calls}
 m=re.search(r'^([0-9a-f]+) <core.local_variables.'+name+r'>:\n(.*?)(?=^[0-9a-f]+ <)',linux,re.M|re.S);assert m
 report['linux'][name]={'va':m[1],'assembly':m[0]}
report['binaries']={p:sha(r/p) for p in ['.work/rot3-20261116/baseline-windows-symbols/bin/sigma.exe','.work/rot3-20261116/baseline-windows-symbols/bin/sigma.pdb','.work/rot3-20261116/baseline-symbols/bin/sigma','zig-out/bin/sigma.exe']}
report['script']=Path(__file__).read_text();(o/'assembly.json').write_text(json.dumps(report,indent=2)+'\n')
print({name:{k:v for k,v in x.items() if k!='assembly'} for name,x in report['windows'].items()})

