from pathlib import Path
import subprocess,json,re,collections,hashlib
r=Path.cwd();o=r/'.work/local-call-20261116';exe=o/'detail/bin/sigma.exe'
cases=[]
for x in json.loads((r/'.work/workload-profile-20261116/results.json').read_text())['cases']:
 cases.append((x['case']['name'],x['profiles'][0]['command'][1:],x['baseline']['stdout']))
for x in json.loads((r/'.work/workload-phases-20261116/results.json').read_text())['cases']:
 if x['name'].endswith('-bake'):cases.append((x['name'],x['runs'][1]['command'][1:],x['runs'][0]['stdout']))
report={'scope':'Compiled PC snapshots only; final dictionary kind used for call classification; no forget/mutation proof for arbitrary programs. Not time.','binary_sha256':hashlib.sha256(exe.read_bytes()).hexdigest(),'cases':[]}
for name,args,expected in cases:
 rows=[]
 for i in [1,2]:
  cmd=[str(exe),*args];p=subprocess.run(cmd,capture_output=True,timeout=240);assert p.returncode==0 and p.stdout.decode()==expected,(name,p.stdout,p.stderr[-300:])
  (o/f'{name}-detail-{i}.stdout').write_bytes(p.stdout);(o/f'{name}-detail-{i}.stderr').write_bytes(p.stderr)
  ops={};details={}
  for line in p.stderr.decode().splitlines():
   if line.startswith('MEASURE-OP '):
    _,pc,count,kind,builtin=line.split();ops[int(pc)]={'count':int(count),'kind':kind,'builtin':builtin}
   elif line.startswith('MEASURE-DETAIL '):
    _,pc,count,category=line.split();details[int(pc)]={'count':int(count),'category':category}
  assert ops.keys()==details.keys()
  counts=collections.Counter()
  for pc,x in ops.items():
   assert x['count']==details[pc]['count']
   if x['kind'] in ['call','call_colon','local_fetch','local_store','local_execute','local_address']:counts[x['kind']+'/'+details[pc]['category']]+=x['count']
  total=int(re.search(r'PROFILE: (\d+) OPERATIONS',p.stderr.decode()).group(1));assert sum(x['count'] for x in ops.values())==total
  rows.append({'command':cmd,'stdout':p.stdout.decode(),'ops':ops,'details':details,'classified_counts':dict(counts.most_common()),'total':total})
 assert rows[0]['ops']==rows[1]['ops'] and rows[0]['details']==rows[1]['details']
 report['cases'].append({'name':name,'runs':rows});(o/'detail-results.json').write_text(json.dumps(report,indent=2)+'\n');print(name,rows[0]['classified_counts'],flush=True)
report['script']=Path(__file__).read_text();report['build_script']=(o/'build-detail.py').read_text();report['build']=json.loads((o/'detail-build.json').read_text());(o/'detail-results.json').write_text(json.dumps(report,indent=2)+'\n')

detail-results.json.build_script:
from pathlib import Path
import subprocess,shutil,json
r=Path.cwd();o=r/'.work/local-call-20261116';s=o/'source';old=r/'.work/workload-profile-20261116/instrumented'
for name in subprocess.check_output(['git','ls-files'],text=True).splitlines():
 if name.startswith(('docs/','.github/')):continue
 p=s/name;p.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(old/name,p)
p=s/'src/core/profiler.zig';text=p.read_text();needle='            writer.add("\\n");\n            words_tools.writeError(machine, writer.text());\n        }\n        if (count == 0) return;';assert text.count(needle)==1
extra='''            writer.add("\\n");
            words_tools.writeError(machine, writer.text());
            var detail = words_debug.LineWriter{ .buffer = &line };
            detail.add("MEASURE-DETAIL "); detail.number(pc); detail.add(" "); detail.number(ran); detail.add(" ");
            switch (op.kind) {
                .call => {
                    if (op.value >= 0 and op.value < machine.word_count) {
                        const word = machine.words[@intCast(op.value)];
                        detail.add(@tagName(word.kind));
                        if (word.has_does) detail.add("-does");
                    } else detail.add("invalid-id");
                },
                .call_colon => detail.add(if (@import("inline_calls.zig").isInline(op)) "inline-marker" else "colon-frame"),
                .local_fetch, .local_store, .local_address, .local_execute => {
                    const kind: @import("defs.zig").LocalKind = @fromBackingInt(@intCast(op.value >> 32));
                    detail.add(@tagName(kind));
                },
                else => detail.add("other"),
            }
            detail.add("\\n"); words_tools.writeError(machine, detail.text());
        }
        if (count == 0) return;'''
text=text.replace(needle,extra);p.write_text(text)
cmd=['zig','build','-Doptimize=fast','-Dcpu=baseline','-Dstrip=true','--prefix',str(o/'detail'),'--summary','all']
with (o/'detail-build.log').open('wb') as f:p=subprocess.run(cmd,cwd=s,stdout=f,stderr=subprocess.STDOUT)
(o/'detail-build.json').write_text(json.dumps({'command':cmd,'exit':p.returncode},indent=2));assert p.returncode==0

probe-checks.json.script:
from pathlib import Path
import subprocess,json,collections
r=Path.cwd();o=r/'.work/local-call-20261116';rows=[]
for name,case in json.loads((o/'linux-results.json').read_text())['cases'].items():
 source=case['commands'][0][-1];expected=[b'99',b'0'] if name=='cell-store' else [b'700',b'0'];runs=[]
 for mode,exe in [('root',r/'zig-out/bin/sigma.exe'),('symbols',r/'.work/rot3-20261116/baseline-windows-symbols/bin/sigma.exe'),('detail',o/'detail/bin/sigma.exe')]:
  cmd=[str(exe),*(['--profile','--measure-profile-reset'] if mode=='detail' else []),'-e',source];p=subprocess.run(cmd,capture_output=True);assert p.returncode==0 and p.stdout.split()==expected,(name,mode,p.stdout,p.stderr[-200:])
  row={'mode':mode,'command':cmd,'stdout':p.stdout.decode(),'exit':p.returncode}
  if mode=='detail':
   ops={};details={}
   for line in p.stderr.decode().splitlines():
    if line.startswith('MEASURE-OP '):
     _,pc,n,kind,builtin=line.split();ops[pc]=(int(n),kind)
    elif line.startswith('MEASURE-DETAIL '):
     _,pc,n,category=line.split();details[pc]=(int(n),category)
   counts=collections.Counter()
   assert ops.keys()==details.keys()
   for pc,(n,kind) in ops.items():assert n==details[pc][0];counts[kind+'/'+details[pc][1]]+=n
   key={'cell-fetch':'local_fetch/cell','char-fetch':'local_fetch/char','double-fetch':'local_fetch/double','float-fetch':'local_fetch/float','xt-execute':'local_execute/xt','cell-store':'local_store/cell'}.get(name)
   if key:assert counts[key]==100,(name,key,counts)
   row['classified_counts']=dict(counts);row['stderr']=p.stderr.decode()
  else:assert not p.stderr
  runs.append(row)
 rows.append({'name':name,'runs':runs})
(o/'probe-checks.json').write_text(json.dumps({'cases':rows,'script':Path(__file__).read_text(),'checks':f'{len(rows)*3} Windows executions exit0 checksum/depth; six expected typed local classification counts exactly100'},indent=2)+'\n');print(len(rows)*3,'executions passed; typed local counts validated')
